-- The contacts list reads a bounded number of rows on a large workspace. contact_tallies counts each workspace's
-- live contacts (exactly the list's count without a term: is_deleted is not 1; a workspace with none has no row),
-- so the page's total reads one row. Each sort and direction has an index in the list's own order (the sort key verbatim, then id ascending in
-- either direction; contacts_name_order in 313 holds name ascending), so a page, and a page after or before a
-- boundary contact, walks its order and stops after its rows. The tally is derived: the migration fills it,
-- triggers on contacts keep it current (imports write rows with plain INSERTs, the widget patches metadata_json),
-- and a restore rebuilds it from the restored rows (scripts/installer/contact-bounds-sql.mjs).
CREATE INDEX contacts_last_seen_asc ON contacts(project_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER),id);
CREATE INDEX contacts_last_seen_desc ON contacts(project_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER) DESC,id);
CREATE INDEX contacts_name_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') COLLATE NOCASE DESC,id);
CREATE INDEX contacts_email_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') COLLATE NOCASE,id);
CREATE INDEX contacts_email_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') COLLATE NOCASE DESC,id);
CREATE INDEX contacts_country_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') COLLATE NOCASE,id);
CREATE INDEX contacts_country_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') COLLATE NOCASE DESC,id);
CREATE TABLE contact_tallies(project_id TEXT PRIMARY KEY NOT NULL,total INTEGER NOT NULL);
INSERT INTO contact_tallies(project_id,total) SELECT project_id,count(*) FROM contacts WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 GROUP BY project_id;
CREATE TRIGGER contact_tallies_insert AFTER INSERT ON contacts WHEN coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1 BEGIN
 INSERT INTO contact_tallies(project_id,total) VALUES(NEW.project_id,1) ON CONFLICT(project_id) DO UPDATE SET total=total+1;
END;
CREATE TRIGGER contact_tallies_delete AFTER DELETE ON contacts WHEN coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1 BEGIN
 UPDATE contact_tallies SET total=total-1 WHERE project_id=OLD.project_id;
 DELETE FROM contact_tallies WHERE project_id=OLD.project_id AND total<=0;
END;
-- A soft delete, an erasure or an undelete flips is_deleted; a move changes the workspace. Other writes change nothing.
CREATE TRIGGER contact_tallies_update AFTER UPDATE OF metadata_json,project_id ON contacts WHEN OLD.project_id IS NOT NEW.project_id OR (coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1) IS NOT (coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1) BEGIN
 UPDATE contact_tallies SET total=total-1 WHERE project_id=OLD.project_id AND coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1;
 DELETE FROM contact_tallies WHERE project_id=OLD.project_id AND total<=0;
 INSERT INTO contact_tallies(project_id,total) SELECT NEW.project_id,1 WHERE coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1 ON CONFLICT(project_id) DO UPDATE SET total=total+1;
END;
-- A term's walk reads only the contacts a non-empty term can match: live, with a name, email, provided name or
-- provided email. Hidden widget drafts have none of them, so neither a broad term's page nor a short term's count
-- steps over them. The list adds this exact predicate to a term's statements (a match implies it), so the planner
-- proves each partial index usable.
CREATE INDEX contacts_searchable_last_seen_asc ON contacts(project_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER),id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_last_seen_desc ON contacts(project_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER) DESC,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_name_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') COLLATE NOCASE,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_name_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') COLLATE NOCASE DESC,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_email_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') COLLATE NOCASE,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_email_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') COLLATE NOCASE DESC,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_country_asc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') COLLATE NOCASE,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
CREATE INDEX contacts_searchable_country_desc ON contacts(project_id,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') COLLATE NOCASE DESC,id) WHERE coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'');
-- contact_search: each live contact with an identity value, scoped to its workspace (the scope column holds the
-- workspace id between two U+0001 characters; a deleted contact or one without identity values has none), with
-- exactly the four values the list searches through SQLite's lower(). A phrase of three or more characters there is
-- the list's ASCII case-insensitive substring match, so a term's total within a workspace is its number of matches,
-- one row each. Each entry carries the contact's id and its four sort keys (unindexed, read through the view), so a
-- term's matches are read with their keys at one row each and ordered whatever their number, and each sort's order
-- text in a band column (indexed; src/modules/management/contact-bands.ts): a text key through lower(), a last seen
-- as the first ten hex digits of its value with the sign bit flipped, between two U+0002 and a U+0003. A phrase of
-- its first characters asks for a band, one stretch of the order, so a page without a total finds a sparse term's
-- matches without reading the stretches between them. Like 310 it is derived:
-- the migration fills it, triggers keep it current, 'rebuild' restores it from contacts, and integrity-check with
-- rank=1 validates it against them; secure-delete removes a changed or erased identity's trigrams from storage.
CREATE VIEW contact_search_identity AS SELECT rowid AS rowid,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(1)||project_id||char(1) ELSE '' END AS scope,lower(coalesce(name,'')) AS name,lower(coalesce(email,'')) AS email,lower(coalesce(json_extract(metadata_json,'$.provided_name'),'')) AS provided_name,lower(coalesce(json_extract(metadata_json,'$.provided_email'),'')) AS provided_email,id AS contact_id,CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER) AS last_seen_key,coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'') AS name_key,coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'') AS email_key,coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'') AS country_key,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(2,2)||substr(substr('89abcdef01234567',instr('0123456789abcdef',substr(printf('%016x',CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER)),1,1)),1)||substr(printf('%016x',CAST(coalesce(json_extract(metadata_json,'$.last_seen_at'),0) AS INTEGER)),2),1,10)||char(3) ELSE '' END AS last_seen_band,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(2,2)||CASE WHEN typeof(coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,''))='text' THEN substr(lower(coalesce(nullif(json_extract(metadata_json,'$.provided_name'),''),name,'')),1,1000000000) ELSE '' END||char(3) ELSE '' END AS name_band,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(2,2)||CASE WHEN typeof(coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,''))='text' THEN substr(lower(coalesce(nullif(json_extract(metadata_json,'$.provided_email'),''),email,'')),1,1000000000) ELSE '' END||char(3) ELSE '' END AS email_band,CASE WHEN coalesce(json_extract(metadata_json,'$.is_deleted'),0)!=1 AND (coalesce(name,'')<>'' OR coalesce(email,'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_name'),'')<>'' OR coalesce(json_extract(metadata_json,'$.provided_email'),'')<>'') THEN char(2,2)||CASE WHEN typeof(coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),''))='text' THEN substr(lower(coalesce(nullif(json_extract(metadata_json,'$.country_name'),''),json_extract(metadata_json,'$.country_code'),'')),1,1000000000) ELSE '' END||char(3) ELSE '' END AS country_band FROM contacts;
CREATE VIRTUAL TABLE contact_search USING fts5(scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id UNINDEXED,last_seen_key UNINDEXED,name_key UNINDEXED,email_key UNINDEXED,country_key UNINDEXED,content='contact_search_identity',content_rowid='rowid',tokenize='trigram case_sensitive 1');
INSERT INTO contact_search(contact_search,rank) VALUES('secure-delete',1);
INSERT INTO contact_search(contact_search) VALUES('rebuild');
CREATE TRIGGER contact_search_insert AFTER INSERT ON contacts BEGIN
 INSERT INTO contact_search(rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key) SELECT rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key FROM contact_search_identity WHERE rowid=NEW.rowid;
END;
CREATE TRIGGER contact_search_delete BEFORE DELETE ON contacts BEGIN
 INSERT INTO contact_search(contact_search,rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key) SELECT 'delete',rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key FROM contact_search_identity WHERE rowid=OLD.rowid;
END;
-- The widget rewrites metadata_json on every session; only a changed identity value, workspace, deleted flag or order
-- text reindexes (a last seen's order text changes once in 2^24 ms; the keys are read through the view).
CREATE TRIGGER contact_search_unindex BEFORE UPDATE OF name,email,metadata_json,project_id ON contacts WHEN OLD.project_id IS NOT NEW.project_id OR OLD.name IS NOT NEW.name OR OLD.email IS NOT NEW.email OR json_extract(OLD.metadata_json,'$.provided_name') IS NOT json_extract(NEW.metadata_json,'$.provided_name') OR json_extract(OLD.metadata_json,'$.provided_email') IS NOT json_extract(NEW.metadata_json,'$.provided_email') OR (coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1) IS NOT (coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1) OR (substr(substr('89abcdef01234567',instr('0123456789abcdef',substr(printf('%016x',CAST(coalesce(json_extract(OLD.metadata_json,'$.last_seen_at'),0) AS INTEGER)),1,1)),1)||substr(printf('%016x',CAST(coalesce(json_extract(OLD.metadata_json,'$.last_seen_at'),0) AS INTEGER)),2),1,10)) IS NOT (substr(substr('89abcdef01234567',instr('0123456789abcdef',substr(printf('%016x',CAST(coalesce(json_extract(NEW.metadata_json,'$.last_seen_at'),0) AS INTEGER)),1,1)),1)||substr(printf('%016x',CAST(coalesce(json_extract(NEW.metadata_json,'$.last_seen_at'),0) AS INTEGER)),2),1,10)) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_name'),''),OLD.name,''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_name'),''),OLD.name,'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_name'),''),NEW.name,''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_name'),''),NEW.name,'')),1,1000000000) ELSE '' END) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_email'),''),OLD.email,''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_email'),''),OLD.email,'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_email'),''),NEW.email,''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_email'),''),NEW.email,'')),1,1000000000) ELSE '' END) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.country_name'),''),json_extract(OLD.metadata_json,'$.country_code'),''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.country_name'),''),json_extract(OLD.metadata_json,'$.country_code'),'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.country_name'),''),json_extract(NEW.metadata_json,'$.country_code'),''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.country_name'),''),json_extract(NEW.metadata_json,'$.country_code'),'')),1,1000000000) ELSE '' END) BEGIN
 INSERT INTO contact_search(contact_search,rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key) SELECT 'delete',rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key FROM contact_search_identity WHERE rowid=OLD.rowid;
END;
CREATE TRIGGER contact_search_reindex AFTER UPDATE OF name,email,metadata_json,project_id ON contacts WHEN OLD.project_id IS NOT NEW.project_id OR OLD.name IS NOT NEW.name OR OLD.email IS NOT NEW.email OR json_extract(OLD.metadata_json,'$.provided_name') IS NOT json_extract(NEW.metadata_json,'$.provided_name') OR json_extract(OLD.metadata_json,'$.provided_email') IS NOT json_extract(NEW.metadata_json,'$.provided_email') OR (coalesce(json_extract(OLD.metadata_json,'$.is_deleted'),0)!=1) IS NOT (coalesce(json_extract(NEW.metadata_json,'$.is_deleted'),0)!=1) OR (substr(substr('89abcdef01234567',instr('0123456789abcdef',substr(printf('%016x',CAST(coalesce(json_extract(OLD.metadata_json,'$.last_seen_at'),0) AS INTEGER)),1,1)),1)||substr(printf('%016x',CAST(coalesce(json_extract(OLD.metadata_json,'$.last_seen_at'),0) AS INTEGER)),2),1,10)) IS NOT (substr(substr('89abcdef01234567',instr('0123456789abcdef',substr(printf('%016x',CAST(coalesce(json_extract(NEW.metadata_json,'$.last_seen_at'),0) AS INTEGER)),1,1)),1)||substr(printf('%016x',CAST(coalesce(json_extract(NEW.metadata_json,'$.last_seen_at'),0) AS INTEGER)),2),1,10)) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_name'),''),OLD.name,''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_name'),''),OLD.name,'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_name'),''),NEW.name,''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_name'),''),NEW.name,'')),1,1000000000) ELSE '' END) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_email'),''),OLD.email,''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.provided_email'),''),OLD.email,'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_email'),''),NEW.email,''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.provided_email'),''),NEW.email,'')),1,1000000000) ELSE '' END) OR (CASE WHEN typeof(coalesce(nullif(json_extract(OLD.metadata_json,'$.country_name'),''),json_extract(OLD.metadata_json,'$.country_code'),''))='text' THEN substr(lower(coalesce(nullif(json_extract(OLD.metadata_json,'$.country_name'),''),json_extract(OLD.metadata_json,'$.country_code'),'')),1,1000000000) ELSE '' END) IS NOT (CASE WHEN typeof(coalesce(nullif(json_extract(NEW.metadata_json,'$.country_name'),''),json_extract(NEW.metadata_json,'$.country_code'),''))='text' THEN substr(lower(coalesce(nullif(json_extract(NEW.metadata_json,'$.country_name'),''),json_extract(NEW.metadata_json,'$.country_code'),'')),1,1000000000) ELSE '' END) BEGIN
 INSERT INTO contact_search(rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key) SELECT rowid,scope,name,email,provided_name,provided_email,last_seen_band,name_band,email_band,country_band,contact_id,last_seen_key,name_key,email_key,country_key FROM contact_search_identity WHERE rowid=NEW.rowid;
END;

-- The cutover page reads a bounded number of rows on a large imported workspace. Its counts were each a walk over the
-- workspace's conversations (the legacy journal has no workspace column, and a widget arrival is told apart from a
-- hidden draft only by its messages). Each counted set is kept here instead, one row per member, with a tally per
-- workspace, so the page reads a tally, the runs that touched the workspace and the widget arrivals after a moment:
-- cutover_zendesk_conversations: a conversation Move in imported from Zendesk that is still in its workspace
--  (cutover/counts.ts zendeskImported).
-- cutover_legacy_conversations: a workspace conversation and each run whose journal maps it (counts.ts legacy);
--  cutover_legacy_runs counts them per workspace and run, so the last sweep reads the runs, live.
-- cutover_widget_arrivals: a conversation a visitor started through the widget and wrote in, with its creation time
--  (counts.ts widgetArrivals without its moment).
-- cutover_tallies: per workspace, the Zendesk and legacy conversations and the widget arrivals of all time.
-- Every row is derived: the migration fills them, and triggers on every table they derive from keep them current
-- (imports write rows with plain INSERTs, so write-path code could not). A restore rebuilds them from the restored rows.
CREATE TABLE cutover_tallies(project_id TEXT PRIMARY KEY,zendesk INTEGER NOT NULL DEFAULT 0,legacy INTEGER NOT NULL DEFAULT 0,widget INTEGER NOT NULL DEFAULT 0) WITHOUT ROWID;
CREATE TABLE cutover_zendesk_conversations(conversation_id TEXT PRIMARY KEY,project_id TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE cutover_legacy_conversations(conversation_id TEXT NOT NULL,run_id TEXT NOT NULL,project_id TEXT NOT NULL,PRIMARY KEY(conversation_id,run_id)) WITHOUT ROWID;
CREATE TABLE cutover_legacy_runs(project_id TEXT NOT NULL,run_id TEXT NOT NULL,conversations INTEGER NOT NULL,PRIMARY KEY(project_id,run_id)) WITHOUT ROWID;
CREATE TABLE cutover_widget_arrivals(conversation_id TEXT PRIMARY KEY,project_id TEXT NOT NULL,created_at INTEGER NOT NULL) WITHOUT ROWID;
-- The arrivals after a moment are one range of this index.
CREATE INDEX cutover_widget_arrivals_since ON cutover_widget_arrivals(project_id,created_at);
-- The tallies follow their sets. A conversation counts once for legacy however many runs map it.
CREATE TRIGGER cutover_zendesk_added AFTER INSERT ON cutover_zendesk_conversations BEGIN
 INSERT INTO cutover_tallies(project_id) SELECT NEW.project_id WHERE NOT EXISTS(SELECT 1 FROM cutover_tallies WHERE project_id=NEW.project_id);
 UPDATE cutover_tallies SET zendesk=zendesk+1 WHERE project_id=NEW.project_id;
END;
CREATE TRIGGER cutover_zendesk_removed AFTER DELETE ON cutover_zendesk_conversations BEGIN
 UPDATE cutover_tallies SET zendesk=zendesk-1 WHERE project_id=OLD.project_id;
 DELETE FROM cutover_tallies WHERE project_id=OLD.project_id AND zendesk=0 AND legacy=0 AND widget=0;
END;
CREATE TRIGGER cutover_widget_added AFTER INSERT ON cutover_widget_arrivals BEGIN
 INSERT INTO cutover_tallies(project_id) SELECT NEW.project_id WHERE NOT EXISTS(SELECT 1 FROM cutover_tallies WHERE project_id=NEW.project_id);
 UPDATE cutover_tallies SET widget=widget+1 WHERE project_id=NEW.project_id;
END;
CREATE TRIGGER cutover_widget_removed AFTER DELETE ON cutover_widget_arrivals BEGIN
 UPDATE cutover_tallies SET widget=widget-1 WHERE project_id=OLD.project_id;
 DELETE FROM cutover_tallies WHERE project_id=OLD.project_id AND zendesk=0 AND legacy=0 AND widget=0;
END;
CREATE TRIGGER cutover_legacy_added AFTER INSERT ON cutover_legacy_conversations BEGIN
 INSERT INTO cutover_legacy_runs(project_id,run_id,conversations) SELECT NEW.project_id,NEW.run_id,0 WHERE NOT EXISTS(SELECT 1 FROM cutover_legacy_runs WHERE project_id=NEW.project_id AND run_id=NEW.run_id);
 UPDATE cutover_legacy_runs SET conversations=conversations+1 WHERE project_id=NEW.project_id AND run_id=NEW.run_id;
 INSERT INTO cutover_tallies(project_id) SELECT NEW.project_id WHERE NOT EXISTS(SELECT 1 FROM cutover_tallies WHERE project_id=NEW.project_id);
 UPDATE cutover_tallies SET legacy=legacy+1 WHERE project_id=NEW.project_id AND NOT EXISTS(SELECT 1 FROM cutover_legacy_conversations l WHERE l.conversation_id=NEW.conversation_id AND l.run_id<>NEW.run_id);
END;
CREATE TRIGGER cutover_legacy_removed AFTER DELETE ON cutover_legacy_conversations BEGIN
 UPDATE cutover_legacy_runs SET conversations=conversations-1 WHERE project_id=OLD.project_id AND run_id=OLD.run_id;
 DELETE FROM cutover_legacy_runs WHERE project_id=OLD.project_id AND run_id=OLD.run_id AND conversations=0;
 UPDATE cutover_tallies SET legacy=legacy-1 WHERE project_id=OLD.project_id AND NOT EXISTS(SELECT 1 FROM cutover_legacy_conversations l WHERE l.conversation_id=OLD.conversation_id);
 DELETE FROM cutover_tallies WHERE project_id=OLD.project_id AND zendesk=0 AND legacy=0 AND widget=0;
END;
INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM move_in_conversations m JOIN conversations c ON c.id=m.conversation_id AND c.project_id=m.project_id WHERE m.vendor='zendesk';
INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,r.run_id,c.project_id FROM legacy_import_rows r JOIN conversations c ON c.id=r.source_id WHERE r.source_table='conversations' AND r.status='mapped';
INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
-- A conversation is added, changed or removed: each of its memberships is read again from its own rows.
CREATE TRIGGER cutover_conversation_added AFTER INSERT ON conversations BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id=NEW.id;
 INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM conversations c WHERE c.id=NEW.id AND EXISTS(SELECT 1 FROM move_in_conversations m WHERE m.conversation_id=c.id AND m.project_id=c.project_id AND m.vendor='zendesk');
 DELETE FROM cutover_legacy_conversations WHERE conversation_id=NEW.id;
 INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,r.run_id,c.project_id FROM conversations c JOIN legacy_import_rows r ON r.source_table='conversations' AND r.source_id=c.id AND r.status='mapped' WHERE c.id=NEW.id;
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=NEW.id;
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=NEW.id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_conversation_changed AFTER UPDATE OF id,project_id,created_at,channel,submitter_type,mailbox_id ON conversations WHEN NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.created_at IS NOT OLD.created_at OR NEW.channel IS NOT OLD.channel OR NEW.submitter_type IS NOT OLD.submitter_type OR NEW.mailbox_id IS NOT OLD.mailbox_id BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id IN (OLD.id,NEW.id);
 INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM conversations c WHERE c.id IN (OLD.id,NEW.id) AND EXISTS(SELECT 1 FROM move_in_conversations m WHERE m.conversation_id=c.id AND m.project_id=c.project_id AND m.vendor='zendesk');
 DELETE FROM cutover_legacy_conversations WHERE conversation_id IN (OLD.id,NEW.id);
 INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,r.run_id,c.project_id FROM conversations c JOIN legacy_import_rows r ON r.source_table='conversations' AND r.source_id=c.id AND r.status='mapped' WHERE c.id IN (OLD.id,NEW.id);
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.id,NEW.id);
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.id,NEW.id) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_conversation_removed AFTER DELETE ON conversations BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id=OLD.id;
 DELETE FROM cutover_legacy_conversations WHERE conversation_id=OLD.id;
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=OLD.id;
END;
-- Move in's record of a Zendesk import: the conversation counts as imported while both exist in one workspace, and an
-- imported conversation is never a widget arrival.
CREATE TRIGGER cutover_move_in_added AFTER INSERT ON move_in_conversations BEGIN
 INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM conversations c WHERE c.id=NEW.conversation_id AND c.project_id=NEW.project_id AND NEW.vendor='zendesk' AND NOT EXISTS(SELECT 1 FROM cutover_zendesk_conversations z WHERE z.conversation_id=NEW.conversation_id);
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=NEW.conversation_id;
END;
CREATE TRIGGER cutover_move_in_changed AFTER UPDATE OF conversation_id,project_id,vendor ON move_in_conversations WHEN NEW.conversation_id IS NOT OLD.conversation_id OR NEW.project_id IS NOT OLD.project_id OR NEW.vendor IS NOT OLD.vendor BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id IN (OLD.conversation_id,NEW.conversation_id);
 INSERT INTO cutover_zendesk_conversations(conversation_id,project_id) SELECT c.id,c.project_id FROM conversations c WHERE c.id IN (OLD.conversation_id,NEW.conversation_id) AND EXISTS(SELECT 1 FROM move_in_conversations m WHERE m.conversation_id=c.id AND m.project_id=c.project_id AND m.vendor='zendesk');
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.conversation_id,NEW.conversation_id);
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.conversation_id,NEW.conversation_id) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_move_in_removed AFTER DELETE ON move_in_conversations BEGIN
 DELETE FROM cutover_zendesk_conversations WHERE conversation_id=OLD.conversation_id;
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=OLD.conversation_id;
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=OLD.conversation_id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
-- The legacy journal names a conversation by its source id, which a legacy conversation keeps natively. The importer
-- writes a conversation and its journal row in either order within a batch; whichever comes second links them. A
-- journaled conversation, mapped or not, is never a widget arrival.
CREATE TRIGGER cutover_journal_added AFTER INSERT ON legacy_import_rows WHEN NEW.source_table='conversations' BEGIN
 INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,NEW.run_id,c.project_id FROM conversations c WHERE c.id=NEW.source_id AND NEW.status='mapped' AND NOT EXISTS(SELECT 1 FROM cutover_legacy_conversations l WHERE l.conversation_id=NEW.source_id AND l.run_id=NEW.run_id);
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=NEW.source_id;
END;
CREATE TRIGGER cutover_journal_changed AFTER UPDATE OF run_id,source_table,source_id,status ON legacy_import_rows WHEN (NEW.source_table='conversations' OR OLD.source_table='conversations') AND (NEW.run_id IS NOT OLD.run_id OR NEW.source_table IS NOT OLD.source_table OR NEW.source_id IS NOT OLD.source_id OR NEW.status IS NOT OLD.status) BEGIN
 DELETE FROM cutover_legacy_conversations WHERE conversation_id IN (OLD.source_id,NEW.source_id);
 INSERT INTO cutover_legacy_conversations(conversation_id,run_id,project_id) SELECT c.id,r.run_id,c.project_id FROM conversations c JOIN legacy_import_rows r ON r.source_table='conversations' AND r.source_id=c.id AND r.status='mapped' WHERE c.id IN (OLD.source_id,NEW.source_id);
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.source_id,NEW.source_id);
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.source_id,NEW.source_id) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_journal_removed AFTER DELETE ON legacy_import_rows WHEN OLD.source_table='conversations' BEGIN
 DELETE FROM cutover_legacy_conversations WHERE conversation_id=OLD.source_id AND run_id=OLD.run_id;
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=OLD.source_id;
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=OLD.source_id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
-- A visitor's message makes a widget conversation an arrival; only removing one can end it. Other messages change nothing.
CREATE TRIGGER cutover_message_added AFTER INSERT ON messages WHEN NEW.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM cutover_widget_arrivals a WHERE a.conversation_id=NEW.conversation_id) BEGIN
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=NEW.conversation_id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_message_changed AFTER UPDATE OF id,project_id,conversation_id,actor_role ON messages WHEN NEW.id IS NOT OLD.id OR NEW.project_id IS NOT OLD.project_id OR NEW.conversation_id IS NOT OLD.conversation_id OR NEW.actor_role IS NOT OLD.actor_role BEGIN
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.conversation_id,NEW.conversation_id);
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.conversation_id,NEW.conversation_id) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_message_removed AFTER DELETE ON messages WHEN OLD.actor_role='contact' AND EXISTS(SELECT 1 FROM cutover_widget_arrivals a WHERE a.conversation_id=OLD.conversation_id) BEGIN
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=OLD.conversation_id;
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=OLD.conversation_id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
-- Mail: a conversation with a receipt, or a visitor message that is a customer's email reply, is not a widget arrival.
CREATE TRIGGER cutover_email_added AFTER INSERT ON inbound_emails WHEN NEW.conversation_id IS NOT NULL OR NEW.message_id IS NOT NULL BEGIN
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (NEW.conversation_id,(SELECT x.conversation_id FROM messages x WHERE x.id=NEW.message_id));
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (NEW.conversation_id,(SELECT x.conversation_id FROM messages x WHERE x.id=NEW.message_id)) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_email_changed AFTER UPDATE OF project_id,conversation_id,message_id ON inbound_emails WHEN NEW.project_id IS NOT OLD.project_id OR NEW.conversation_id IS NOT OLD.conversation_id OR NEW.message_id IS NOT OLD.message_id BEGIN
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.conversation_id,NEW.conversation_id,(SELECT x.conversation_id FROM messages x WHERE x.id=OLD.message_id),(SELECT x.conversation_id FROM messages x WHERE x.id=NEW.message_id));
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.conversation_id,NEW.conversation_id,(SELECT x.conversation_id FROM messages x WHERE x.id=OLD.message_id),(SELECT x.conversation_id FROM messages x WHERE x.id=NEW.message_id)) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_email_removed AFTER DELETE ON inbound_emails WHEN OLD.conversation_id IS NOT NULL OR OLD.message_id IS NOT NULL BEGIN
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.conversation_id,(SELECT x.conversation_id FROM messages x WHERE x.id=OLD.message_id));
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.conversation_id,(SELECT x.conversation_id FROM messages x WHERE x.id=OLD.message_id)) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
-- A follow-up the system opened is not a widget arrival.
CREATE TRIGGER cutover_followup_added AFTER INSERT ON ticket_followups BEGIN
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=NEW.conversation_id;
END;
CREATE TRIGGER cutover_followup_changed AFTER UPDATE OF conversation_id ON ticket_followups WHEN NEW.conversation_id IS NOT OLD.conversation_id BEGIN
 DELETE FROM cutover_widget_arrivals WHERE conversation_id IN (OLD.conversation_id,NEW.conversation_id);
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id IN (OLD.conversation_id,NEW.conversation_id) AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
CREATE TRIGGER cutover_followup_removed AFTER DELETE ON ticket_followups BEGIN
 DELETE FROM cutover_widget_arrivals WHERE conversation_id=OLD.conversation_id;
 INSERT INTO cutover_widget_arrivals(conversation_id,project_id,created_at) SELECT c.id,c.project_id,c.created_at FROM conversations c WHERE c.id=OLD.conversation_id AND c.channel='widget' AND c.submitter_type='contact' AND c.mailbox_id IS NULL AND NOT EXISTS(SELECT 1 FROM inbound_emails e WHERE e.project_id=c.project_id AND e.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM move_in_conversations i WHERE i.conversation_id=c.id) AND NOT EXISTS(SELECT 1 FROM legacy_import_rows l WHERE l.source_table='conversations' AND l.source_id=c.id) AND NOT EXISTS(SELECT 1 FROM ticket_followups f WHERE f.conversation_id=c.id) AND EXISTS(SELECT 1 FROM messages m WHERE m.project_id=c.project_id AND m.conversation_id=c.id AND m.actor_role='contact' AND NOT EXISTS(SELECT 1 FROM inbound_emails r WHERE r.project_id=m.project_id AND r.message_id=m.id));
END;
